  const toggleFullscreen = useCallback(async () => { try { if (!isFullscreen) { const e = containerRef.current; if (e?.requestFullscreen) { await e.requestFullscreen(); setIsFullscreen(true); } } else { if (document.fullscreenElement) await document.exitFullscreen(); setIsFullscreen(false); } } catch (e) { console.error('Fullscreen error:', e); } }, [isFullscreen]);
  useEffect(() => { const h = () => setIsFullscreen(!!document.fullscreenElement); document.addEventListener('fullscreenchange', h); return () => document.removeEventListener('fullscreenchange', h); }, []);

  const showFeedback = useCallback((message, type) => { if (feedbackTimeoutRef.current) clearTimeout(feedbackTimeoutRef.current); setFeedback(message); setFeedbackType(type); feedbackTimeoutRef.current = setTimeout(() => { setFeedback(''); setFeedbackType(''); }, 500); }, []);
  const initAudio = useCallback(() => { try { if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || window.webkitAudioContext)(); if (audioCtxRef.current.state === 'suspended') audioCtxRef.current.resume(); return audioCtxRef.current; } catch (e) { return null; } }, []);

  const playSound = useCallback((type) => { if (!soundEnabled) return; try { const a = initAudio(); if (!a) return; const o = a.createOscillator(); const g = a.createGain(); o.connect(g); g.connect(a.destination); const n = a.currentTime; if (type === 'correct') { o.frequency.setValueAtTime(880, n); g.gain.setValueAtTime(0.12, n); } else if (type === 'wrong') { o.frequency.setValueAtTime(440, n); g.gain.setValueAtTime(0.1, n); } else if (type === 'streak') { o.frequency.setValueAtTime(1046, n); g.gain.setValueAtTime(0.12, n); } o.start(n); g.gain.exponentialRampToValueAtTime(0.001, n + 0.15); o.stop(n + 0.15); } catch (e) {} }, [soundEnabled, initAudio]);

  const endGame = useCallback(() => { if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; } if (cycleTimeoutRef.current) clearTimeout(cycleTimeoutRef.current); if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current); setGameState('gameOver'); gameStateRef.current = 'gameOver'; isActiveRef.current = false; const acc = totalRef.current > 0 ? Math.round((correctRef.current / totalRef.current) * 100) : 100; setAccuracy(acc); updateBestScore(scoreRef.current); }, [updateBestScore]);

  const startTimer = useCallback(() => { if (timerIntervalRef.current) clearInterval(timerIntervalRef.current); timerIntervalRef.current = setInterval(() => { if (gameStateRef.current === 'playing' && isActiveRef.current) { if (timeLeftRef.current <= 1) { if (timerIntervalRef.current) { clearInterval(timerIntervalRef.current); timerIntervalRef.current = null; } endGame(); } else { timeLeftRef.current -= 1; setTimeLeft(timeLeftRef.current); } } }, 1000); }, [endGame]);

  const safeEvaluate = useCallback((a, b, op) => { switch(op) { case '+': return a + b; case '-': return a - b; case '*': return a * b; default: return 0; } }, []);

  const fail = useCallback((reason) => { if (!isActiveRef.current) return; totalRef.current++; setTotalAttempts(totalRef.current); const pp = 1; if (livesRef.current > 0) { livesRef.current -= 1; setLives(livesRef.current); } streakRef.current = 0; setStreak(0); scoreRef.current = Math.max(0, scoreRef.current - pp); setScore(scoreRef.current); windowTimeRef.current = Math.min(1500, windowTimeRef.current + 100); setWindowTime(windowTimeRef.current); feedbackColorRef.current = '#1a0000'; stateRef.current = "FEEDBACK"; setFlashState("FEEDBACK"); playSound('wrong'); if (livesRef.current === 0) { showFeedback(`✗ ${reason}! -${pp}pt | No lives left!`, 'error'); } else { showFeedback(`✗ ${reason}! -${pp}pt | ${livesRef.current} lives left`, 'error'); } if (cycleTimeoutRef.current) clearTimeout(cycleTimeoutRef.current); if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current); cycleTimeoutRef.current = setTimeout(() => { if (isActiveRef.current && gameStateRef.current === 'playing') startCycle(); }, 800); }, [playSound, showFeedback]);

  const handleSuccess = useCallback((reactionTime) => { if (!isActiveRef.current) return; totalRef.current++; correctRef.current++; setTotalAttempts(totalRef.current); setCorrectAnswers(correctRef.current); setLastReaction(reactionTime); if (bestReaction === 0 || reactionTime < bestReaction) setBestReaction(reactionTime); streakRef.current++; setStreak(streakRef.current); if (streakRef.current > bestStreakRef.current) { bestStreakRef.current = streakRef.current; setBestStreak(bestStreakRef.current); } scoreRef.current += 1; setScore(scoreRef.current); windowTimeRef.current = Math.max(600, windowTimeRef.current - 40); setWindowTime(windowTimeRef.current); feedbackColorRef.current = '#001a05'; stateRef.current = "FEEDBACK"; setFlashState("FEEDBACK"); if (streakRef.current % 5 === 0) { playSound('streak'); showFeedback(`🔥 ${streakRef.current} Streak! +1`, 'success'); } else { playSound('correct'); showFeedback(`✓ ${reactionTime}ms | +1`, 'success'); } if (cycleTimeoutRef.current) clearTimeout(cycleTimeoutRef.current); if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current); cycleTimeoutRef.current = setTimeout(() => { if (isActiveRef.current && gameStateRef.current === 'playing') startCycle(); }, 300); }, [bestReaction, playSound, showFeedback]);

  const generateMath = useCallback(() => { if (!isActiveRef.current) return; const ops = ['+', '-', '*']; const op = ops[Math.floor(Math.random() * ops.length)]; let a, b; if (op === '*') { a = Math.floor(Math.random() * 10) + 1; b = Math.floor(Math.random() * 9) + 1; } else { a = Math.floor(Math.random() * 50) + 1; b = Math.floor(Math.random() * 50) + 1; } const eq = `${a} ${op} ${b}`; const res = safeEvaluate(a, b, op); equationRef.current = eq; resultRef.current = res; setEquation(eq); stateRef.current = "FLASH"; setFlashState("FLASH"); startTimeRef.current = performance.now(); feedbackColorRef.current = isBoxDarkMode ? '#020202' : '#f9fafb'; if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current); flashTimeoutRef.current = setTimeout(() => { if (stateRef.current === "FLASH") { stateRef.current = "WAITING"; setFlashState("WAITING"); } }, 800); if (cycleTimeoutRef.current) clearTimeout(cycleTimeoutRef.current); cycleTimeoutRef.current = setTimeout(() => { if ((stateRef.current === "FLASH" || stateRef.current === "WAITING") && isActiveRef.current) fail("TIMEOUT"); }, windowTimeRef.current); }, [isBoxDarkMode, safeEvaluate, fail]);

  const startCycle = useCallback(() => { if (!isActiveRef.current) return; stateRef.current = "IDLE"; setFlashState("IDLE"); if (cycleTimeoutRef.current) clearTimeout(cycleTimeoutRef.current); cycleTimeoutRef.current = setTimeout(() => { if (isActiveRef.current && gameStateRef.current === 'playing') generateMath(); }, 800 + Math.random() * 1000); }, [generateMath]);

