    const ro = new ResizeObserver(() => hr()); if (containerRef.current) ro.observe(containerRef.current);
    return () => { if (animationRef.current) cancelAnimationFrame(animationRef.current); window.removeEventListener('resize', hr); ro.disconnect(); };
